package org.springframework.samples.petclinic.rest.function.owner;

import java.util.regex.Pattern;

import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;

/**
 * Validates the optional owner {@code postcode}. Postcode is absent when null or blank; when present it
 * must be a 4-digit value and, when the city maps to a known region, fall within that region's fixed
 * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
 * postcode. The postcode is stored and returned as given (trimmed).
 */
final class Postcode {

    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");

    private Postcode() {
    }

    /**
     * @return the trimmed postcode, or {@code null} when it is absent (null or blank).
     * @throws InvalidPostcodeException when present but not a 4-digit value, or out of range for the
     *         city's region.
     */
    static String normalize(String postcode, String city) throws InvalidPostcodeException {
        if (postcode == null || postcode.isBlank()) {
            return null;
        }
        String trimmed = postcode.trim();
        if (!FOUR_DIGITS.matcher(trimmed).matches()) {
            throw new InvalidPostcodeException(postcode);
        }
        String region = OwnerRegion.regionForCity(city);
        if (region != null) {
            int[] range = OwnerRegion.rangeForRegion(region);
            int value = Integer.parseInt(trimmed);
            if (value < range[0] || value > range[1]) {
                throw new InvalidPostcodeException(postcode);
            }
        }
        return trimmed;
    }
}
===== OwnerRegion =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

/**
 * The single source of truth for an owner's canonical region, derived from the postcode and city. A
 * region is a short code (NSW, VIC, QLD) fixed by two lookup tables: the inclusive 4-digit postcode
 * range per region, and the city-to-region fallback used when the postcode yields nothing.
 *
 * <p>{@link #fromPostcode} answers the region for a postcode alone (or {@code null}) and is the source
 * of the REGION component of an owner's {@code customerCode}; {@link #regionOf} reads that component
 * back out of a {@code customerCode}, which is how a whole owner resolves to a locality.
 */
public final class OwnerRegion {

    /** City -> canonical region, from the fixed city-to-region table. */
    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /** Region -> inclusive 4-digit postcode range {low, high}. */
    private static final Map<String, int[]> REGION_RANGE = Map.of(
            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});

    private OwnerRegion() {
    }

    /** The canonical region for {@code city} from the fixed city-to-region table, or {@code null}. */
    static String regionForCity(String city) {
        return city == null ? null : CITY_REGION.get(city);
    }

    /** The inclusive 4-digit postcode range {low, high} for {@code region}, or {@code null}. */
    static int[] rangeForRegion(String region) {
        return REGION_RANGE.get(region);
    }

    /**
     * The region whose fixed range contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
     * QLD 4000-4099), or {@code null} when the postcode is absent, non-numeric, or in no known range.
     */
    public static String fromPostcode(String postcode) {
        if (postcode == null || postcode.isBlank()) {
            return null;
        }
        int value;
        try {
            value = Integer.parseInt(postcode.trim());
        }
        catch (NumberFormatException ex) {
            return null;
        }
        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }

    /**
     * The REGION component of a {@code customerCode} ({@code <REGION>-<HASH8>}) — the owner's locality.
     * Now that identity is region-and-hash, the locality is read straight off the assigned code rather
     * than recomputed, so it always matches the code. {@code UNKNOWN} when the code is absent or has no
     * region component.
     */
    public static String regionOf(String customerCode) {
        if (customerCode == null) {
            return "UNKNOWN";
        }
        int dash = customerCode.indexOf('-');
        return dash < 0 ? "UNKNOWN" : customerCode.substring(0, dash);
    }
}
===== BusinessDays =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.DayOfWeek;
import java.time.LocalDate;

/**
 * The registration date must fall on a business day. A date landing on a Saturday or Sunday rolls
 * forward to the following Monday; a weekday is left unchanged. Applied to the effective registration
 * date — whether supplied in the request or defaulted to the server date — so every value derived
 * from the registration date (membership number year, per-day create limit) sees the adjusted date.
 */
final class BusinessDays {

    private BusinessDays() {
    }

    /** Roll a weekend date forward to the next Monday; return a weekday unchanged. */
    static LocalDate rollForward(LocalDate date) {
        LocalDate rolled = date;
        while (rolled.getDayOfWeek() == DayOfWeek.SATURDAY
                || rolled.getDayOfWeek() == DayOfWeek.SUNDAY) {
            rolled = rolled.plusDays(1);
        }
        return rolled;
    }
}

=====DuplicateIdentityException=====
package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown when a create-owner request's derived {@code identityKey} (normalizedTelephone + '|' +
 * (email or empty) + '|' + householdId) exactly equals an existing owner's identityKey. This one key
 * subsumes the former separate telephone, email and household duplicate checks. Handled globally by
 * {@link DuplicateIdentityExceptionHandler}, which responds 409.
 */
public class DuplicateIdentityException extends Exception {

    private final String identityKey;

    public DuplicateIdentityException(String identityKey) {
        super("An owner with the same identity already exists: " + identityKey);
        this.identityKey = identityKey;
    }

    public String getIdentityKey() {
        return this.identityKey;
    }
}
=====DuplicateIdentityExceptionHandler=====
package org.springframework.samples.petclinic.rest.escalation;

import java.util.List;
import java.util.Map;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

/**
 * Responds 409 when a create-owner request's derived {@code identityKey} exactly equals an existing
 * owner's identityKey.
 */
public class DuplicateIdentityExceptionHandler {

    public void handle(@Parameter DuplicateIdentityException ex,
            ObjectResponse<ResponseEntity<Map<String, List<String>>>> response) {
        response.send(new ResponseEntity<>(Map.of("errors", List.of("identityKey")), HttpStatus.CONFLICT));
    }
}
